@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : int
  + name : string
  + energyClass : EnergyClass
  + address : string
  + yearOfConstruction : int
}

enum EnergyClass {
  A
  B
  C
  D
}

class AdditionalEntry {
  + name : string
  + isPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + value : double
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + email : string
  + password : string
  + isActivated : boolean
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + text : string
}

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User
WebPortal "1" -- "*" Comment
Building "1" *-- "*" AdditionalEntry
Building "1" *-- "*" Image
Building "1" "0..1" -- "1" Image : profile photo
User "1" -- "*" Building : owner
User "1" -- "*" Comment : author
Building "1" -- "*" Comment : subject

@enduml

